update public.learning_paths
set
  title = 'HR Analytics / HRIS',
  goal = 'HR Analytics / HRIS',
  summary = 'This advanced undergraduate course prepares Human Resources students to work confidently with HRIS platforms, workforce data, dashboards, and responsible people analytics. The course covers core topics through a complete capstone-level sequence that reflects leading HR programs, current HR technology practice, and the growing governance demands around employee data and AI.',
  data = $hrahjson${"slug": "hr-analytics-hris", "title": "HR Analytics / HRIS", "description": "This advanced undergraduate course prepares Human Resources students to work confidently with HRIS platforms, workforce data, dashboards, and responsible people analytics. The course covers core topics through a complete capstone-level sequence that reflects leading HR programs, current HR technology practice, and the growing governance demands around employee data and AI.", "topics": [{"id": "a2f2a9f4-b3f9-4259-8cae-5ea80d002339", "type": "topic", "title": "Strategic People Analytics and Evidence-Based HR", "description": "This opening section frames HR analytics as a management discipline: students learn to convert workforce questions into evidence, decisions, and measurable business or mission outcomes.", "children": [{"id": "c31155be-b75c-4e61-8dd8-38a82bce1f8d", "type": "subtopic", "title": "People analytics value chain", "children": [{"id": "317a59ee-ff17-4adb-abeb-11b5a0331f91", "type": "concept", "title": "business questions"}, {"id": "1715ada8-6ac1-46fa-9be3-aec247896e61", "type": "concept", "title": "decision rights"}, {"id": "f79dd4b0-e04e-4cab-bc00-55730f1de682", "type": "concept", "title": "hypothesis framing"}, {"id": "bca8d98e-4968-4b4c-a382-7725ca8d2be8", "type": "concept", "title": "insight-to-action pathways"}, {"id": "0f717c9d-e9f2-456f-928f-228816114171", "type": "concept", "title": "impact measurement"}], "description": "Students learn how raw HR data becomes insight only when it is linked to a real workforce problem, a decision maker, and an action."}, {"id": "6c213aa1-4f14-4f30-ba2a-53aae2980c6e", "type": "subtopic", "title": "Evidence-based HR", "children": [{"id": "456f00a3-071d-47d8-bc58-974a6a1bc70e", "type": "concept", "title": "research literacy"}, {"id": "94968d0e-56fd-4d98-8f7d-bc392f5e3d24", "type": "concept", "title": "internal evidence"}, {"id": "7fab21f8-ea1f-487e-aff8-e48f70b66d04", "type": "concept", "title": "external benchmarks"}, {"id": "e51be395-341b-46d1-99fa-e1841fda07ad", "type": "concept", "title": "managerial judgment"}, {"id": "86d71b0f-dc58-4527-877e-de1ca1a2c562", "type": "concept", "title": "limits of correlation"}], "description": "This subtopic teaches students to combine internal data, research evidence, stakeholder judgment, and ethical constraints rather than relying on anecdotes or dashboard theater."}, {"id": "d63403c2-b250-4c0e-89a0-cb1f6533915a", "type": "subtopic", "title": "HR metrics strategy", "children": [{"id": "f2562ed6-383c-486f-b3de-4b202fcd104e", "type": "concept", "title": "leading and lagging indicators"}, {"id": "e4ecb22e-7b99-4ecb-ab5d-9ab4652e6c4d", "type": "concept", "title": "metric definitions"}, {"id": "ebdf11ca-e16a-44a3-b55f-d7315637a8b1", "type": "concept", "title": "KPI governance"}, {"id": "6ee3d0fe-a651-474e-b25a-d1db8dc6fe73", "type": "concept", "title": "target setting"}, {"id": "d6c0ad86-7cd4-49ff-9fa6-ef86b6881550", "type": "concept", "title": "balanced scorecards"}], "description": "Students distinguish vanity metrics from measures that support strategic workforce planning, talent investment, and organizational learning."}]}, {"id": "767b83e7-996d-429b-90b7-d94477cf9dcc", "type": "topic", "title": "HRIS Architecture and HR Technology Ecosystems", "description": "Students map the systems that hold workforce data and learn why architecture decisions shape data quality, employee experience, compliance, and analytics maturity.", "children": [{"id": "886aebae-159f-4105-8d97-8c2b2b2832b1", "type": "subtopic", "title": "Core HRIS design", "children": [{"id": "ce5167ec-0433-4cb7-89e1-c42a8125cb87", "type": "concept", "title": "employee master data"}, {"id": "6c60d6a2-36e5-47af-b917-cad985c0b1ee", "type": "concept", "title": "position management"}, {"id": "fae7ca18-2319-4387-9fb4-9eb5fdb253c1", "type": "concept", "title": "organizational hierarchy"}, {"id": "f6064aed-eb3e-4f72-af21-a7ba9b1da3dc", "type": "concept", "title": "workflow approvals"}, {"id": "8630819b-fefe-4dfb-8de2-8dcd2866bced", "type": "concept", "title": "effective-dated records"}], "description": "This subtopic explains the central employee record and the workflows that depend on it."}, {"id": "f7085481-878f-4380-bbce-00e956ff967a", "type": "subtopic", "title": "HR technology stack", "children": [{"id": "93469433-7803-48a1-8134-446b9c9798d2", "type": "concept", "title": "ATS"}, {"id": "1e5e2604-3cef-4019-85d3-40fad3aa8081", "type": "concept", "title": "payroll"}, {"id": "9f073fca-1d0d-43a7-985a-3cd8596d2999", "type": "concept", "title": "benefits administration"}, {"id": "ed52e608-f474-486e-bf6f-ea1b46bb881d", "type": "concept", "title": "LMS"}, {"id": "6f0d7490-e59c-4a28-a3d8-b0e7b416e07d", "type": "concept", "title": "performance platforms"}, {"id": "1ce47a0a-e0a0-4b6a-a9ca-341162e9711e", "type": "concept", "title": "engagement tools"}], "description": "Students learn how recruiting, payroll, benefits, learning, performance, engagement, and workforce planning systems fit together."}, {"id": "86ee9153-0193-43b4-b33a-40242e7d06e9", "type": "subtopic", "title": "Integration and interoperability", "children": [{"id": "6a6cd2da-b8b7-4b75-a6e8-c310e4a154a0", "type": "concept", "title": "APIs"}, {"id": "f105b3e9-2000-4d44-acc0-92e80b4bc1a9", "type": "concept", "title": "SFTP feeds"}, {"id": "bc60161a-4a1b-450a-8827-0b37be19ad7c", "type": "concept", "title": "single sign-on"}, {"id": "ddd39b20-28ac-46f5-abcb-558273971df2", "type": "concept", "title": "HR Open Standards"}, {"id": "44e0e82d-27d0-41c5-acbe-2e21cc7c2937", "type": "concept", "title": "data dictionaries"}, {"id": "d2c1e649-8d8e-48e9-9db5-6a93a7976b49", "type": "concept", "title": "system-of-record rules"}], "description": "The course introduces the practical language of APIs, file feeds, identity management, and HR data standards."}]}, {"id": "ff575f1d-64ea-4e0e-8fbe-d771139250f2", "type": "topic", "title": "Workforce Data Governance, Quality, and Stewardship", "description": "This section teaches students that analytics quality begins before analysis: definitions, ownership, access, validation, and stewardship determine whether HR data can be trusted.", "children": [{"id": "2f765d07-a7fd-44ed-8fcb-bf822b0de05f", "type": "subtopic", "title": "Data governance roles", "children": [{"id": "0c03711c-6994-470e-8efc-6eb68ad04860", "type": "concept", "title": "data owners"}, {"id": "ad1702e4-ab04-439f-b5ef-45113882b9c8", "type": "concept", "title": "data stewards"}, {"id": "284cab93-4733-4a2c-a701-5c175d283d58", "type": "concept", "title": "data custodians"}, {"id": "369ad5bd-8ffe-4522-80ea-1f3ed65635d1", "type": "concept", "title": "RACI models"}, {"id": "07339fd4-e202-4c0b-834a-a99a4a2b96e3", "type": "concept", "title": "governance councils"}], "description": "Students identify who owns, defines, approves, changes, and audits HR data across the organization."}, {"id": "75a7a639-58c1-413a-9a47-dc6998accb97", "type": "subtopic", "title": "Data quality management", "children": [{"id": "7ec41f8d-0c09-4344-9dc6-3377fbde4523", "type": "concept", "title": "missing data"}, {"id": "395db124-d141-4feb-9e22-ff5cefba6daa", "type": "concept", "title": "duplicate records"}, {"id": "d9019594-8595-441f-b58a-534464b2f274", "type": "concept", "title": "outliers"}, {"id": "efc1abb4-fb30-4e4f-9f5c-b6482b4f1865", "type": "concept", "title": "date logic"}, {"id": "4f56ceb1-2343-4e66-98b2-2981c51aad11", "type": "concept", "title": "validation rules"}, {"id": "0f31f5ba-4711-4e46-9a4b-3bb1f5172560", "type": "concept", "title": "master data cleanup"}], "description": "Students learn to detect and fix common HR data issues that distort dashboards and workforce decisions."}, {"id": "474a20d2-2fad-4543-8e55-d549691d3c1a", "type": "subtopic", "title": "Metric definitions and data dictionaries", "children": [{"id": "0cd3a2bb-2d97-4cc8-9ece-303ac4a6d8ed", "type": "concept", "title": "headcount definitions"}, {"id": "4ec5ecff-59d3-49d7-a52a-a302fd274190", "type": "concept", "title": "FTE"}, {"id": "a6196a7a-873d-42fb-9706-1c8648624734", "type": "concept", "title": "turnover formulas"}, {"id": "9f94373d-96e3-4be7-977f-88d21606fb23", "type": "concept", "title": "internal mobility"}, {"id": "556f2b03-bd05-409a-8e4f-6e632ceea963", "type": "concept", "title": "diversity dimensions"}, {"id": "c30004d6-50a6-4b3a-a712-66feccdafbd5", "type": "concept", "title": "calculation lineage"}], "description": "This subtopic shows why shared definitions are essential for comparability across functions, time periods, and leaders."}]}, {"id": "d8257089-842b-4da9-85d3-74cfb1ea98d0", "type": "topic", "title": "HR Data Modeling, Reporting, and SQL Foundations", "description": "Students build the technical fluency needed to ask better questions of HR systems, collaborate with analysts, and understand how reports are produced.", "children": [{"id": "59de4d89-a889-472f-b128-cc5dff9945b8", "type": "subtopic", "title": "Relational HR data", "children": [{"id": "383d02e3-03ef-47c3-9bde-b19a6e377919", "type": "concept", "title": "primary keys"}, {"id": "e44a7200-7560-4d71-ac36-64d2b9c3798e", "type": "concept", "title": "foreign keys"}, {"id": "77fec94c-3479-436b-ba0b-053a1bae35a6", "type": "concept", "title": "employee IDs"}, {"id": "813d6caa-53f0-4517-a7cd-80931a7dd860", "type": "concept", "title": "job tables"}, {"id": "b2dc6341-bbfe-4556-abb9-f573ac289a3f", "type": "concept", "title": "position tables"}, {"id": "99ef3b06-e171-456c-bc4f-85b78949c3f4", "type": "concept", "title": "effective dates"}], "description": "This subtopic introduces the table structures behind employee, job, compensation, recruiting, learning, and performance data."}, {"id": "1e363a53-b642-4839-bec0-ed5d4bab05de", "type": "subtopic", "title": "Query logic for HR questions", "children": [{"id": "41e53ae1-581f-4248-92c9-59d110fb7809", "type": "concept", "title": "joins"}, {"id": "b12574cb-6ba3-4da5-a072-ce6e000e7a96", "type": "concept", "title": "filters"}, {"id": "638d5903-7e79-4383-b0cb-04e1e51c9491", "type": "concept", "title": "grouping"}, {"id": "c0aaf9b9-fb16-4be1-a8f7-c50863dc43a9", "type": "concept", "title": "cohort selection"}, {"id": "32f9ff4b-c20b-4ca1-be5b-fe37200ec7ec", "type": "concept", "title": "time windows"}, {"id": "0bf6cdd9-3247-4ae2-b418-ba956ddaeec0", "type": "concept", "title": "data extracts"}], "description": "Students learn the logic of joins, filters, aggregations, and cohorts so they can audit reports and specify analytic requirements."}, {"id": "686e5047-56e7-4c40-8ff7-6cb80eabd74a", "type": "subtopic", "title": "Reporting controls", "children": [{"id": "024d1a5f-c35b-4915-9b75-1c9cb40a5fe0", "type": "concept", "title": "report catalogs"}, {"id": "94b9eb60-00a5-4a85-b555-b8c5f5dc4197", "type": "concept", "title": "refresh schedules"}, {"id": "10d2d446-1a76-4f74-b5d6-ad86558fa80a", "type": "concept", "title": "row-level security"}, {"id": "ffbf8d70-c158-4bf9-ac2c-f5f08f746914", "type": "concept", "title": "reconciliation"}, {"id": "0b0b0715-1ab4-4bb0-8d78-75fe6370461f", "type": "concept", "title": "change logs"}], "description": "Students learn how recurring HR reports should be checked, versioned, documented, and protected."}]}, {"id": "82275c7d-ed66-4435-8dbf-4d34b10ce9fa", "type": "topic", "title": "HR Dashboards and Data Visualization", "description": "This section focuses on communicating workforce evidence clearly enough that leaders can diagnose problems, compare patterns, and choose action.", "children": [{"id": "a97d53c5-1d2a-4031-b678-f8b3df1e45ba", "type": "subtopic", "title": "Dashboard design", "children": [{"id": "5b5d1d2d-8a12-46ab-b1e3-874c5f496321", "type": "concept", "title": "executive dashboards"}, {"id": "b5a7bac4-cfba-4625-8954-a72f3288c271", "type": "concept", "title": "manager dashboards"}, {"id": "e410e5d4-5bd5-4ff4-a4b5-ea9cb6caf6de", "type": "concept", "title": "operational reports"}, {"id": "b2a21018-5286-4e53-a448-b7e78ee1907b", "type": "concept", "title": "drilldowns"}, {"id": "543e4408-236f-41fc-9883-84f79b553c13", "type": "concept", "title": "alerts"}], "description": "Students learn to design dashboards around decisions and audiences, not around every available metric."}, {"id": "ca919b83-5b04-402a-933d-d2cde7caa8b6", "type": "subtopic", "title": "Visualization choices", "children": [{"id": "ab3c290c-807b-426c-aff5-55f6eb47dbbd", "type": "concept", "title": "trend lines"}, {"id": "ddd36dd0-2fc7-4b8f-8ed5-3b5d8ebf0497", "type": "concept", "title": "bar charts"}, {"id": "70d5d8e8-1960-43e3-b020-638b6062786a", "type": "concept", "title": "funnel charts"}, {"id": "640d9790-cfdf-40ef-b0b2-fe68bb36f418", "type": "concept", "title": "heat maps"}, {"id": "0febb145-f488-417d-8256-54b1a1c77de2", "type": "concept", "title": "small multiples"}, {"id": "e08eef7e-f976-434c-888f-581389e9fc69", "type": "concept", "title": "accessibility"}], "description": "This subtopic develops judgment about which chart type fits the workforce question and how to avoid misleading displays."}, {"id": "485d976a-54f1-4212-be40-6b4ec4e05905", "type": "subtopic", "title": "Narrative and insight communication", "children": [{"id": "92e130a5-4927-4c3a-90ce-346ce5d6aaf1", "type": "concept", "title": "insight headlines"}, {"id": "d559c35f-8b92-4636-a595-17454e37fc71", "type": "concept", "title": "annotation"}, {"id": "a86effcb-e76f-4f30-babc-b4f5041f6d4d", "type": "concept", "title": "context notes"}, {"id": "559845ae-4e39-401a-8da1-22d76348fb01", "type": "concept", "title": "confidence language"}, {"id": "f1df082f-007d-4997-b0e6-6ad0a0860f18", "type": "concept", "title": "recommendation framing"}], "description": "Students practice explaining what changed, why it matters, what is uncertain, and what action is recommended."}]}, {"id": "fe20e5d0-c85c-4d8b-83d8-b3f901e1c17d", "type": "topic", "title": "Descriptive and Diagnostic HR Analytics", "description": "Students learn to move beyond counting activity toward explaining workforce patterns across units, roles, demographics, managers, and time.", "children": [{"id": "10e5ae77-89f1-4fa9-9552-73bd29bda7a9", "type": "subtopic", "title": "Descriptive workforce metrics", "children": [{"id": "69c88b5f-d407-4c51-9818-578dee25e27a", "type": "concept", "title": "headcount"}, {"id": "ab3bf486-80f7-4a01-a81d-7e164622c87d", "type": "concept", "title": "FTE"}, {"id": "2b060956-4500-4d56-8ece-bb5b27c0f847", "type": "concept", "title": "hires"}, {"id": "74cf63e9-427e-4b89-b05d-26e97b254197", "type": "concept", "title": "terminations"}, {"id": "ed738651-64bd-40c5-9a64-765783b03493", "type": "concept", "title": "absence"}, {"id": "8f7b5083-69f7-4daa-b6b7-604ae4e74852", "type": "concept", "title": "promotion rates"}, {"id": "2440060c-3b88-44c6-85cd-b6dbe2d6eeb4", "type": "concept", "title": "time to fill"}], "description": "This subtopic covers the standard measurements that form the base layer of HR analytics."}, {"id": "df6c5e17-6937-4a21-a42f-2f7490caf3f4", "type": "subtopic", "title": "Segmentation and comparison", "children": [{"id": "f9ee2a15-4112-400e-a3d7-4f77f117beb6", "type": "concept", "title": "business units"}, {"id": "b8ed0bd1-faf9-4042-b5cf-a5e69fcc4e36", "type": "concept", "title": "job families"}, {"id": "c0714f02-05a0-4b48-82dd-6237b136e792", "type": "concept", "title": "location"}, {"id": "d3eaf342-8fc7-4c12-993e-1dbf008bd489", "type": "concept", "title": "tenure bands"}, {"id": "b8f98444-fc6b-4399-b7c6-3cc7060f6e4a", "type": "concept", "title": "manager groups"}, {"id": "e26b436c-a142-4a30-94c5-2a5010a5c4b0", "type": "concept", "title": "minimum cell sizes"}], "description": "Students learn how to compare groups responsibly without overgeneralizing or exposing sensitive identities."}, {"id": "17070b09-2b02-41f3-bf07-3b96cdd20929", "type": "subtopic", "title": "Root-cause diagnosis", "children": [{"id": "bc122f1c-1b45-4553-b26b-f9022a1d9c67", "type": "concept", "title": "process mapping"}, {"id": "71007057-4525-4b74-8735-e96f96e7a833", "type": "concept", "title": "driver trees"}, {"id": "92f80043-b074-45c1-85bc-fb34a0f4c563", "type": "concept", "title": "fishbone analysis"}, {"id": "858a3e8d-9ce3-40fc-a306-8e98bec326ad", "type": "concept", "title": "qualitative triangulation"}, {"id": "c36f11d0-7b3a-4eb8-b641-0143e2f0099c", "type": "concept", "title": "action hypotheses"}], "description": "The course connects data patterns to interviews, process review, and operational context."}]}, {"id": "ebdcbf93-db79-49e2-b0ed-270de023d247", "type": "topic", "title": "Predictive Analytics for Workforce Decisions", "description": "This section introduces predictive thinking while emphasizing that models must be interpretable, validated, and used with human judgment.", "children": [{"id": "00e8e3d0-b3bf-4c48-917e-21c542091c8a", "type": "subtopic", "title": "Prediction concepts", "children": [{"id": "b5d7c0f6-0a75-4a37-850c-6a2ab30e3ae1", "type": "concept", "title": "training and test data"}, {"id": "b1dcae8a-0ece-4d25-b97e-59f94aa33985", "type": "concept", "title": "features"}, {"id": "2f57bec9-cce5-4563-9bdc-34f3e3e910de", "type": "concept", "title": "labels"}, {"id": "62d8cbd4-1b03-48ee-84e0-a35c4ba8c171", "type": "concept", "title": "overfitting"}, {"id": "21651139-07bb-45da-b405-d42435c7a812", "type": "concept", "title": "accuracy"}, {"id": "8a483617-6be9-4135-9c22-74642d35f9db", "type": "concept", "title": "precision and recall"}], "description": "Students learn the basic concepts behind forecasting and classification without treating models as magic decision engines."}, {"id": "a579850b-ed0f-47eb-9d33-a8bc1870ffcc", "type": "subtopic", "title": "Workforce forecasting", "children": [{"id": "ec57cc97-3c70-4b22-adbe-64ad1db3d1d1", "type": "concept", "title": "demand forecasting"}, {"id": "1d7bfff2-3812-4306-a032-b2903d693623", "type": "concept", "title": "supply forecasting"}, {"id": "ea5c3758-4ad4-40ce-a9ef-1b6d32531dca", "type": "concept", "title": "scenario planning"}, {"id": "177f898a-b776-4a02-82b4-afb7cc98f7bb", "type": "concept", "title": "skills supply"}, {"id": "fcf7162f-ad99-4e55-aad4-ebdd52c110e4", "type": "concept", "title": "succession risk"}], "description": "This subtopic uses historical and operational data to anticipate staffing needs, talent supply, and capacity risk."}, {"id": "55d80d3e-8f8a-4b40-9d09-cb2be0b4f6f9", "type": "subtopic", "title": "Model interpretation and limits", "children": [{"id": "04c76778-8104-4258-bcc6-14cb0202f4a0", "type": "concept", "title": "explainability"}, {"id": "ea38377c-cd61-4d79-9217-5470a4ea8528", "type": "concept", "title": "feature importance"}, {"id": "7dd546c7-eba8-4b8a-b4b0-fc3e1de88e80", "type": "concept", "title": "false positives"}, {"id": "161e16cc-32a4-40c2-9669-ecb8b036a231", "type": "concept", "title": "bias testing"}, {"id": "f6c20fbe-dbcf-4d7a-8320-00155ff2b70d", "type": "concept", "title": "human review"}], "description": "Students learn to ask what a model is really predicting, where it fails, and how it could harm employees if misused."}]}, {"id": "4c7c40ae-9d2d-4c46-8dd2-a33b98ea2bd5", "type": "topic", "title": "Turnover, Retention, and Employee Movement Analytics", "description": "Students examine how people enter, move through, and leave organizations, with a focus on interpreting patterns and designing targeted interventions.", "children": [{"id": "25a75072-b312-400d-83df-844c109751a3", "type": "subtopic", "title": "Turnover measurement", "children": [{"id": "f10b4ddf-7ce6-4a0a-82c1-d6a842bcbd59", "type": "concept", "title": "voluntary turnover"}, {"id": "b7e9bb44-c55e-4f14-9c2a-12172603fb1c", "type": "concept", "title": "involuntary turnover"}, {"id": "e642f027-5352-4586-a858-76c2806dd4cf", "type": "concept", "title": "regretted loss"}, {"id": "9a5bacad-e997-432e-ba5c-8c303e0161fc", "type": "concept", "title": "new-hire turnover"}, {"id": "3fd4b1c3-ce08-4539-91be-cfe366e0f469", "type": "concept", "title": "annualized rates"}], "description": "This subtopic clarifies how turnover rates differ by definition, population, time period, and business question."}, {"id": "fe051868-ab80-4970-9a97-a605fe8ec125", "type": "subtopic", "title": "Retention drivers", "children": [{"id": "27b92ded-d948-4ddb-b742-00d07746dd3b", "type": "concept", "title": "manager effects"}, {"id": "1a8c4186-d3c4-4ccf-9aff-8fd4854b99de", "type": "concept", "title": "compensation equity"}, {"id": "7c8853f7-fbb2-426f-918c-5f836797fcde", "type": "concept", "title": "career paths"}, {"id": "048c8d89-4319-48f1-a409-0a8ff19f3be0", "type": "concept", "title": "workload"}, {"id": "b103c249-cc52-4a0c-95df-132b2ca05e24", "type": "concept", "title": "commute and flexibility"}, {"id": "db128afb-7b94-4608-9280-d8c474ebb291", "type": "concept", "title": "labor market pressure"}], "description": "Students learn to connect turnover patterns with engagement, pay, manager quality, career opportunity, workload, and labor-market context."}, {"id": "6172c950-96b9-4ab8-b2f2-90a1eb2fb010", "type": "subtopic", "title": "Internal mobility", "children": [{"id": "33c36d8c-97e3-40af-a99a-967c95286f3b", "type": "concept", "title": "promotions"}, {"id": "db9dbcb5-dad7-4d45-8f39-fedbec35c530", "type": "concept", "title": "lateral moves"}, {"id": "6c5bc7a8-a6e8-4c21-b401-2483cd584cf0", "type": "concept", "title": "talent marketplaces"}, {"id": "5a223dd5-c5a4-4b1c-9554-31e3c7338b60", "type": "concept", "title": "career mobility"}, {"id": "db5acd7a-0c07-4a80-bf57-6282354bf8e5", "type": "concept", "title": "succession pipelines"}], "description": "The course treats movement inside the organization as a critical retention and capability strategy."}]}, {"id": "e9b34837-cb72-45a0-96f5-0ffaad4ed733", "type": "topic", "title": "Engagement, Employee Experience, and Listening Analytics", "description": "This section teaches students to measure employee voice carefully and translate findings into credible action.", "children": [{"id": "75096a0d-2743-44b6-8c58-d0a8ac218fd2", "type": "subtopic", "title": "Survey design and interpretation", "children": [{"id": "65b6af44-77ae-4324-a4ba-0c4b6ac7f156", "type": "concept", "title": "construct validity"}, {"id": "5735f398-b25a-4fd3-bcc7-f89030782761", "type": "concept", "title": "question wording"}, {"id": "6cb4d239-1a2d-4925-9605-931f1ce804c0", "type": "concept", "title": "response rates"}, {"id": "149d1005-4792-4ef5-8357-ad2895cea175", "type": "concept", "title": "sampling"}, {"id": "e0d873a1-fa08-42ff-aaac-69c804565122", "type": "concept", "title": "benchmarking"}, {"id": "a74c1604-6522-4674-8205-50afd4348b34", "type": "concept", "title": "survey fatigue"}], "description": "Students learn what makes engagement, pulse, onboarding, and exit surveys useful or misleading."}, {"id": "9f4da684-268d-40ca-b703-763edb3a269e", "type": "subtopic", "title": "Driver analysis", "children": [{"id": "aaf28a65-eab6-49a9-8e89-eefe2d16496b", "type": "concept", "title": "correlation"}, {"id": "e8e3909c-9480-4b5e-a349-0272f24e9eab", "type": "concept", "title": "regression"}, {"id": "490bb53a-a18d-4fe0-aa6b-f10395b86d78", "type": "concept", "title": "relative importance"}, {"id": "2744b76e-16ed-4b6f-955e-bcb8031b70c2", "type": "concept", "title": "manager effects"}, {"id": "f3b52ce7-bedc-4910-bc18-c77fb4ef47b7", "type": "concept", "title": "confidence intervals"}], "description": "This subtopic shows how to identify the factors most strongly associated with outcomes such as engagement, retention, and performance."}, {"id": "58198d8e-3a22-4f05-9338-16d109ba0f17", "type": "subtopic", "title": "Employee listening systems", "children": [{"id": "a6ebf8e1-f7ad-4648-9f46-8d351ce29961", "type": "concept", "title": "pulse surveys"}, {"id": "c477c5a2-17dd-4dc1-a0f2-8a36a8f84de6", "type": "concept", "title": "focus groups"}, {"id": "e85a683a-47a2-44cf-ba7a-955252a7a40f", "type": "concept", "title": "open-text themes"}, {"id": "93fdd179-d59d-49de-aaf7-346b79af8fa0", "type": "concept", "title": "case analytics"}, {"id": "75d75fd7-5306-464a-b062-c7e2e03baa5a", "type": "concept", "title": "listening ethics"}], "description": "Students learn how surveys, interviews, focus groups, case data, and passive signals should be combined with consent and care."}]}, {"id": "7447b75d-d6e8-4f01-99a3-6187ef37dfec", "type": "topic", "title": "DEI, Pay Equity, and Fairness Analytics", "description": "Students learn to use HR data to identify inequity, test workforce processes, and support fairer talent systems while avoiding simplistic or performative metrics.", "children": [{"id": "73988e31-7b2f-477c-babb-c77433a83cc7", "type": "subtopic", "title": "Representation and flow metrics", "children": [{"id": "24e73043-ce63-4ea8-9a91-9bf0878db1b3", "type": "concept", "title": "representation"}, {"id": "78f4a6ce-4c68-49cd-a992-dbc92a625798", "type": "concept", "title": "selection rates"}, {"id": "609f4d59-18c0-4cd1-95b9-48f14585d2a5", "type": "concept", "title": "promotion rates"}, {"id": "6df87849-1949-4c53-8e39-e31f8fe44356", "type": "concept", "title": "succession slates"}, {"id": "926aab58-7ce3-4b3b-b751-65efdd81c817", "type": "concept", "title": "attrition gaps"}, {"id": "7c4c3133-7000-4b09-ab61-8afb7faef590", "type": "concept", "title": "intersectionality"}], "description": "This subtopic analyzes workforce composition and movement through hiring, promotion, development, and exit points."}, {"id": "f4342336-0c03-43b1-8ad2-a50b5fed6af3", "type": "subtopic", "title": "Pay equity analysis", "children": [{"id": "3492292c-11f5-4690-92ee-84e2feb04739", "type": "concept", "title": "job level controls"}, {"id": "9201107f-fe84-4ef6-b9da-60ba19427791", "type": "concept", "title": "tenure controls"}, {"id": "4670317c-958d-4780-baa0-491edcb4e6a3", "type": "concept", "title": "regression analysis"}, {"id": "1592b82e-8217-4669-9cb4-dcf5aa245f70", "type": "concept", "title": "compa-ratio"}, {"id": "ab4cab71-7e67-4d50-b53f-d49634d00341", "type": "concept", "title": "unexplained gaps"}], "description": "Students learn the logic of controlled pay comparisons and the limits of simple averages."}, {"id": "d827345f-1203-4432-bb97-bbd1835f3c9b", "type": "subtopic", "title": "Fairness audits", "children": [{"id": "465951c7-126d-4d5e-bc5f-e1d911ec5ef9", "type": "concept", "title": "four-fifths rule"}, {"id": "b484faa4-84d4-4da1-9f97-f813a4eca3fe", "type": "concept", "title": "selection procedure validity"}, {"id": "a67f1a64-3f0d-4e43-a576-b9ffe082e152", "type": "concept", "title": "AI hiring audits"}, {"id": "4b5c1f81-1e5a-4ead-aa62-d0c4291c59cf", "type": "concept", "title": "accessibility"}, {"id": "91d9afb6-26d6-43fd-9125-2a45faddef62", "type": "concept", "title": "documentation"}], "description": "The course introduces adverse impact, algorithmic bias, accommodation, and audit trails for talent systems."}]}, {"id": "d87fbfc6-d9d3-4173-8a1d-9df3dd035782", "type": "topic", "title": "Skills, Learning, and Workforce Planning Analytics", "description": "This section makes the course more current by adding skills intelligence: students learn how organizations map capabilities, plan talent supply, and target development investments.", "children": [{"id": "831182d1-8df4-4000-9baa-03d1afa739bb", "type": "subtopic", "title": "Skills taxonomy and ontology", "children": [{"id": "ff6b1926-3780-46a4-919e-56d779e4ecc5", "type": "concept", "title": "skills taxonomies"}, {"id": "958975b5-599c-42d7-8838-d75d39789268", "type": "concept", "title": "skills ontologies"}, {"id": "5f798cc3-9d1e-423e-af17-248aab71b1ec", "type": "concept", "title": "proficiency levels"}, {"id": "19b28ec3-6674-42ce-a2aa-5c175738ede3", "type": "concept", "title": "job architecture"}, {"id": "6b8908b3-80b3-446e-9161-b40a551091ea", "type": "concept", "title": "skills validation"}], "description": "Students learn how organizations define, group, update, and govern skills data."}, {"id": "f2155c66-8cc2-4eac-aa80-6c4bba8e3b41", "type": "subtopic", "title": "Learning analytics", "children": [{"id": "ca731fe0-bc97-4c54-b0bc-99c1e66cb9f7", "type": "concept", "title": "completion metrics"}, {"id": "b27c4957-a08a-43dc-b5d8-3b3cb2ba0b91", "type": "concept", "title": "learning transfer"}, {"id": "2a239260-da08-41ac-a24e-2640ee258529", "type": "concept", "title": "assessment evidence"}, {"id": "278f4c24-d66f-4ac7-a7b1-b0c3a7db3a85", "type": "concept", "title": "upskilling pathways"}, {"id": "e197069c-34d5-4eb9-be36-cf293d238183", "type": "concept", "title": "ROI limits"}], "description": "This subtopic links learning activity to capability growth, performance, mobility, and business outcomes."}, {"id": "29bd06de-3bda-456d-aae6-b571109e46ec", "type": "subtopic", "title": "Strategic workforce planning", "children": [{"id": "85af1a12-6c76-43d0-9f39-db4c80024129", "type": "concept", "title": "scenario planning"}, {"id": "53bb9c9a-6f38-446d-9b6c-04af4ca3c9d8", "type": "concept", "title": "gap analysis"}, {"id": "c5b1a75f-4b83-4302-bb68-5d54f3e897d1", "type": "concept", "title": "build-buy-borrow"}, {"id": "0a6d59de-9d27-47a1-be1f-b4d0ae400fcc", "type": "concept", "title": "critical roles"}, {"id": "95578c53-3e31-4e55-8fc2-451a7220c0ca", "type": "concept", "title": "workforce risk"}], "description": "Students learn to compare future demand with internal supply and design talent build-buy-borrow strategies."}]}, {"id": "39afe7fb-39f5-4b56-b2f2-c25d91996998", "type": "topic", "title": "Privacy, Security, Ethics, and Responsible AI in HR", "description": "This section gives students the governance judgment needed to work with sensitive employee data and emerging HR technologies responsibly.", "children": [{"id": "83dcf38c-e426-4b17-9531-66b9287d6625", "type": "subtopic", "title": "Employee data privacy", "children": [{"id": "6ee26f78-cb60-433f-b9d7-d7076fe0b87c", "type": "concept", "title": "data minimization"}, {"id": "09cf5260-72f9-4897-bb23-0f1f1c09c02b", "type": "concept", "title": "purpose limitation"}, {"id": "6a9892e8-4c52-474c-8331-b0d899823c89", "type": "concept", "title": "consent limits"}, {"id": "5fa78606-e0a7-4442-8c38-60449a6a0d16", "type": "concept", "title": "retention schedules"}, {"id": "1b757e31-3fba-4ec7-b5d4-b81bad447411", "type": "concept", "title": "employee notice"}], "description": "Students learn why HR data requires special care because it affects employment, identity, health, pay, and workplace power."}, {"id": "b57f4cd7-ee56-4525-971f-47d28da057f4", "type": "subtopic", "title": "Security and access controls", "children": [{"id": "76ab08be-88d5-435b-871f-c664bcffebcd", "type": "concept", "title": "role-based access"}, {"id": "da5a9df7-e869-486f-b750-07ab97bac7fa", "type": "concept", "title": "least privilege"}, {"id": "c113b5e1-4d1f-43db-b1e5-b45d22c21a3f", "type": "concept", "title": "audit logs"}, {"id": "96cb4f13-23fa-40b4-a78a-a6b4746b9896", "type": "concept", "title": "encryption"}, {"id": "4f0a44b7-9af8-4b31-86e3-f4afb6d64df3", "type": "concept", "title": "vendor access"}, {"id": "510555fa-624b-4ba8-89dc-c9f06542c171", "type": "concept", "title": "incident response"}], "description": "This subtopic introduces practical controls for preventing unauthorized access, leakage, and misuse of HR data."}, {"id": "92e8548d-9e5d-4b94-abdf-4e6a3b038889", "type": "subtopic", "title": "Responsible AI governance", "children": [{"id": "c06afd50-105c-4dab-b2c5-b3a5564c5363", "type": "concept", "title": "model cards"}, {"id": "34c61741-ad50-4f2c-b313-280f41bdb685", "type": "concept", "title": "bias audits"}, {"id": "0cfad42d-0955-46e6-a805-8cbe215492a1", "type": "concept", "title": "explainability"}, {"id": "a4000bf2-5cfe-4cc5-a467-cb88bd570abb", "type": "concept", "title": "procurement review"}, {"id": "d5e4a5d3-6434-474a-8ba6-0190df2d8e8b", "type": "concept", "title": "human oversight"}, {"id": "2c9ff45d-f817-4723-93dc-62b764767ba9", "type": "concept", "title": "appeals"}], "description": "Students learn to evaluate AI tools for hiring, performance, scheduling, learning, and employee listening."}]}, {"id": "4e063eea-3b13-4f55-b535-ed3880d707b3", "type": "topic", "title": "HR Technology Selection, Implementation, and Change Adoption", "description": "Students learn that HRIS success is not only a 